insert into public.bible_verses (id, book_key, book_name, chapter, verse, content, sort_order)
values
('1ki-22-20','1ki','열왕기상',22,20,'여호와께서 말씀하시기를 누가 아합을 꾀어 그를 길르앗 라못에 올라가서 죽게 할꼬 하시니 하나는 이렇게 하겠다 하고 또 하나는 저렇게 하겠다 하였는데',9501),
('1ki-22-21','1ki','열왕기상',22,21,'한 영이 나아와 여호와 앞에 서서 말하되 내가 그를 꾀겠나이다',9502),
('1ki-22-22','1ki','열왕기상',22,22,'여호와께서 그에게 이르시되 어떻게 하겠느냐 이르되 내가 나가서 거짓말하는 영이 되어 그의 모든 선지자들의 입에 있겠나이다 여호와께서 이르시되 너는 꾀겠고 또 이루리라 나가서 그리하라 하셨은즉',9503),
('1ki-22-23','1ki','열왕기상',22,23,'이제 여호와께서 거짓말하는 영을 왕의 이 모든 선지자의 입에 넣으셨고 또 여호와께서 왕에 대하여 화를 말씀하셨나이다',9504),
('1ki-22-24','1ki','열왕기상',22,24,'그나아나의 아들 시드기야가 가까이 와서 미가야의 뺨을 치며 이르되 여호와의 영이 나를 떠나 어디로 가서 네게 말씀하시더냐',9505),
('1ki-22-25','1ki','열왕기상',22,25,'미가야가 이르되 네가 골방에 들어가서 숨는 그 날에 보리라',9506),
('1ki-22-26','1ki','열왕기상',22,26,'이스라엘의 왕이 이르되 미가야를 잡아 성주 아몬과 왕자 요아스에게로 끌고 돌아가서',9507),
('1ki-22-27','1ki','열왕기상',22,27,'말하기를 왕의 말씀이 이 놈을 옥에 가두고 내가 평안히 돌아올 때까지 고생의 떡과 고생의 물을 먹이라 하였다 하라',9508),
('1ki-22-28','1ki','열왕기상',22,28,'미가야가 이르되 왕이 참으로 평안히 돌아오시게 될진대 여호와께서 나를 통하여 말씀하지 아니하셨으리이다 또 이르되 너희 백성들아 다 들을지어다 하니라',9509),
('1ki-22-29','1ki','열왕기상',22,29,'이스라엘의 왕과 유다의 여호사밧 왕이 길르앗 라못으로 올라가니라',9510),
('1ki-22-30','1ki','열왕기상',22,30,'이스라엘의 왕이 여호사밧에게 이르되 나는 변장하고 전쟁터로 들어가려 하노니 당신은 왕복을 입으소서 하고 이스라엘의 왕이 변장하고 전쟁터로 들어가니라',9511),
('1ki-22-31','1ki','열왕기상',22,31,'아람 왕이 그의 병거의 지휘관 삼십이 명에게 명령하여 이르기를 너희는 작은 자나 큰 자와 더불어 싸우지 말고 오직 이스라엘 왕과 싸우라 한지라',9512),
('1ki-22-32','1ki','열왕기상',22,32,'병거의 지휘관들이 여호사밧을 보고 그들이 이르되 이가 틀림없이 이스라엘의 왕이라 하고 돌이켜 그와 싸우려 한즉 여호사밧이 소리를 지르는지라',9513),
('1ki-22-33','1ki','열왕기상',22,33,'병거의 지휘관들이 그가 이스라엘의 왕이 아님을 보고 쫓기를 그치고 돌이켰더라',9514),
('1ki-22-34','1ki','열왕기상',22,34,'한 사람이 무심코 활을 당겨 이스라엘 왕의 갑옷 솔기를 맞힌지라 왕이 그 병거 모는 자에게 이르되 내가 부상하였으니 네 손을 돌려 내가 전쟁터에서 나가게 하라 하였으나',9515),
('1ki-22-35','1ki','열왕기상',22,35,'이 날에 전쟁이 맹렬하였으므로 왕이 병거 가운데에 붙들려 서서 아람 사람을 막다가 저녁에 이르러 죽었는데 상처의 피가 흘러 병거 바닥에 고였더라',9516),
('1ki-22-36','1ki','열왕기상',22,36,'해가 질 녘에 진중에서 외치는 소리가 있어 이르되 각기 성읍으로 또는 각기 본향으로 가라 하더라',9517),
('1ki-22-37','1ki','열왕기상',22,37,'왕이 이미 죽으매 그의 시체를 메어 사마리아에 이르러 왕을 사마리아에 장사하니라',9518),
('1ki-22-38','1ki','열왕기상',22,38,'그 병거를 사마리아 못에서 씻으매 개들이 그의 피를 핥았으니 여호와께서 하신 말씀과 같이 되었더라 거기는 창기들이 목욕하는 곳이었더라',9519),
('1ki-22-39','1ki','열왕기상',22,39,'아합의 남은 행적과 그가 행한 모든 일과 그가 건축한 상아궁과 그가 건축한 모든 성읍은 이스라엘 왕 역대지략에 기록되지 아니하였느냐',9520),
('1ki-22-40','1ki','열왕기상',22,40,'아합이 그의 조상들과 함께 자매 그의 아들 아하시야가 대신하여 왕이 되니라',9521),
('1ki-22-41','1ki','열왕기상',22,41,'이스라엘의 아합 왕 제사년에 아사의 아들 여호사밧이 유다의 왕이 되니',9522),
('1ki-22-42','1ki','열왕기상',22,42,'여호사밧이 왕이 될 때에 나이가 삼십오 세라 예루살렘에서 이십오 년 동안 다스리니라 그의 어머니의 이름은 아수바라 실히의 딸이더라',9523),
('1ki-22-43','1ki','열왕기상',22,43,'여호사밧이 그의 아버지 아사의 모든 길로 행하며 돌이키지 아니하고 여호와 앞에서 정직히 행하였으나 산당은 폐하지 아니하였으므로 백성이 아직도 산당에서 제사를 드리며 분향하였더라',9524),
('1ki-22-44','1ki','열왕기상',22,44,'여호사밧이 이스라엘의 왕과 더불어 화평하니라',9525),
('1ki-22-45','1ki','열왕기상',22,45,'여호사밧의 남은 사적과 그가 부린 권세와 그가 어떻게 전쟁하였는지는 다 유다 왕 역대지략에 기록되지 아니하였느냐',9526),
('1ki-22-46','1ki','열왕기상',22,46,'그가 그의 아버지 아사의 시대에 남아 있던 남색하는 자들을 그 땅에서 쫓아내었더라',9527),
('1ki-22-47','1ki','열왕기상',22,47,'그 때에 에돔에는 왕이 없고 섭정 왕이 있었더라',9528),
('1ki-22-48','1ki','열왕기상',22,48,'여호사밧이 다시스의 선박을 제조하고 오빌로 금을 구하러 보내려 하였더니 그 배가 에시온게벨에서 파선하였으므로 가지 못하게 되매',9529),
('1ki-22-49','1ki','열왕기상',22,49,'아합의 아들 아하시야가 여호사밧에게 이르되 내 종으로 당신의 종과 함께 배에 가게 하라 하나 여호사밧이 허락하지 아니하였더라',9530),
('1ki-22-50','1ki','열왕기상',22,50,'여호사밧이 그의 조상들과 함께 자매 그의 조상 다윗 성에 그의 조상들과 함께 장사되고 그의 아들 여호람이 대신하여 왕이 되니라',9531),
('1ki-22-51','1ki','열왕기상',22,51,'유다의 여호사밧 왕 제십칠년에 아합의 아들 아하시야가 사마리아에서 이스라엘의 왕이 되어 이 년 동안 이스라엘을 다스리니라',9532),
('1ki-22-52','1ki','열왕기상',22,52,'그가 여호와 앞에서 악을 행하여 그의 아버지의 길과 그의 어머니의 길과 이스라엘에게 범죄하게 한 느밧의 아들 여로보암의 길로 행하며',9533),
('1ki-22-53','1ki','열왕기상',22,53,'바알을 섬겨 그에게 예배하여 이스라엘의 하나님 여호와를 노하시게 하기를 그의 아버지의 온갖 행위 같이 하였더라',9534),
('2ki-1-1','2ki','열왕기하',1,1,'아합이 죽은 후에 모압이 이스라엘을 배반하였더라',9535),
('2ki-1-2','2ki','열왕기하',1,2,'아하시야가 사마리아에 있는 그의 다락 난간에서 떨어져 병들매 사자를 보내며 그들에게 이르되 가서 에그론의 신 바알세붑에게 이 병이 낫겠나 물어 보라 하니라',9536),
('2ki-1-3','2ki','열왕기하',1,3,'여호와의 사자가 디셉 사람 엘리야에게 이르되 너는 일어나 올라가서 사마리아 왕의 사자를 만나 그에게 이르기를 이스라엘에 하나님이 없어서 너희가 에그론의 신 바알세붑에게 물으러 가느냐',9537),
('2ki-1-4','2ki','열왕기하',1,4,'그러므로 여호와의 말씀이 네가 올라간 침상에서 내려오지 못할지라 네가 반드시 죽으리라 하셨다 하라 엘리야가 이에 가니라',9538),
('2ki-1-5','2ki','열왕기하',1,5,'사자들이 왕에게 돌아오니 왕이 그들에게 이르되 너희는 어찌하여 돌아왔느냐 하니',9539),
('2ki-1-6','2ki','열왕기하',1,6,'그들이 말하되 한 사람이 올라와서 우리를 만나 이르되 너희는 너희를 보낸 왕에게로 돌아가서 그에게 고하기를 여호와의 말씀이 이스라엘에 하나님이 없어서 네가 에그론의 신 바알세붑에게 물으려고 보내느냐 그러므로 네가 올라간 침상에서 내려오지 못할지라 네가 반드시 죽으리라 하셨다 하라 하더이다',9540),
('2ki-1-7','2ki','열왕기하',1,7,'왕이 그들에게 이르되 올라와서 너희를 만나 이 말을 너희에게 한 그 사람은 어떤 사람이더냐',9541),
('2ki-1-8','2ki','열왕기하',1,8,'그들이 그에게 대답하되 그는 털이 많은 사람인데 허리에 가죽 띠를 띠었더이다 하니 왕이 이르되 그는 디셉 사람 엘리야로다',9542),
('2ki-1-9','2ki','열왕기하',1,9,'이에 오십부장과 그의 군사 오십 명을 엘리야에게로 보내매 그가 엘리야에게로 올라가 본즉 산 꼭대기에 앉아 있는지라 그가 엘리야에게 이르되 하나님의 사람이여 왕의 말씀이 내려오라 하셨나이다',9543),
('2ki-1-10','2ki','열왕기하',1,10,'엘리야가 오십부장에게 대답하여 이르되 내가 만일 하나님의 사람이면 불이 하늘에서 내려와 너와 너의 오십 명을 사를지로다 하매 불이 곧 하늘에서 내려와 그와 그의 군사 오십 명을 살랐더라',9544),
('2ki-1-11','2ki','열왕기하',1,11,'왕이 다시 다른 오십부장과 그의 군사 오십 명을 엘리야에게로 보내니 그가 엘리야에게 말하여 이르되 하나님의 사람이여 왕의 말씀이 속히 내려오라 하셨나이다 하니',9545),
('2ki-1-12','2ki','열왕기하',1,12,'엘리야가 그들에게 대답하여 이르되 내가 만일 하나님의 사람이면 불이 하늘에서 내려와 너와 너의 오십 명을 사를지로다 하매 하나님의 불이 곧 하늘에서 내려와 그와 그의 군사 오십 명을 살랐더라',9546),
('2ki-1-13','2ki','열왕기하',1,13,'왕이 세 번째 오십부장과 그의 군사 오십 명을 보낸지라 셋째 오십부장이 올라가서 엘리야 앞에 이르러 그의 무릎을 꿇어 엎드려 간구하여 이르되 하나님의 사람이여 원하건대 나의 생명과 당신의 종인 이 오십 명의 생명을 당신은 귀히 보소서',9547),
('2ki-1-14','2ki','열왕기하',1,14,'불이 하늘에서 내려와 전번의 오십부장 둘과 그의 군사 오십 명을 살랐거니와 나의 생명을 당신은 귀히 보소서 하매',9548),
('2ki-1-15','2ki','열왕기하',1,15,'여호와의 사자가 엘리야에게 이르되 너는 그를 두려워하지 말고 함께 내려가라 하신지라 엘리야가 곧 일어나 그와 함께 내려와 왕에게 이르러',9549),
('2ki-1-16','2ki','열왕기하',1,16,'말하되 여호와의 말씀이 네가 사자를 보내 에그론의 신 바알세붑에게 물으려 하니 이스라엘에 그의 말을 물을 만한 하나님이 안 계심이냐 그러므로 네가 그 올라간 침상에서 내려오지 못할지라 네가 반드시 죽으리라 하셨다 하니라',9550),
('2ki-1-17','2ki','열왕기하',1,17,'왕이 엘리야가 전한 여호와의 말씀대로 죽고 그가 아들이 없으므로 여호람이 그를 대신하여 왕이 되니 유다 왕 여호사밧의 아들 여호람의 둘째 해였더라',9551),
('2ki-1-18','2ki','열왕기하',1,18,'아하시야가 행한 그 남은 사적은 모두 이스라엘 왕 역대지략에 기록되지 아니하였느냐',9552),
('2ki-2-1','2ki','열왕기하',2,1,'여호와께서 회오리 바람으로 엘리야를 하늘로 올리고자 하실 때에 엘리야가 엘리사와 더불어 길갈에서 나가더니',9553),
('2ki-2-2','2ki','열왕기하',2,2,'엘리야가 엘리사에게 이르되 청하건대 너는 여기 머물라 여호와께서 나를 벧엘로 보내시느니라 하니 엘리사가 이르되 여호와께서 살아 계심과 당신의 영혼이 살아 있음을 두고 맹세하노니 내가 당신을 떠나지 아니하겠나이다 하는지라 이에 두 사람이 벧엘로 내려가니',9554),
('2ki-2-3','2ki','열왕기하',2,3,'벧엘에 있는 선지자의 제자들이 엘리사에게로 나아와 그에게 이르되 여호와께서 오늘 당신의 선생을 당신의 머리 위로 데려가실 줄을 아시나이까 하니 이르되 나도 또한 아노니 너희는 잠잠하라 하니라',9555),
('2ki-2-4','2ki','열왕기하',2,4,'엘리야가 그에게 이르되 엘리사야 청하건대 너는 여기 머물라 여호와께서 나를 여리고로 보내시느니라 엘리사가 이르되 여호와께서 살아 계심과 당신의 영혼이 살아 있음을 두고 맹세하노니 내가 당신을 떠나지 아니하겠나이다 하니라 그들이 여리고에 이르매',9556),
('2ki-2-5','2ki','열왕기하',2,5,'여리고에 있는 선지자의 제자들이 엘리사에게 나아와 이르되 여호와께서 오늘 당신의 선생을 당신의 머리 위로 데려가실 줄을 아시나이까 하니 엘리사가 이르되 나도 아노니 너희는 잠잠하라',9557),
('2ki-2-6','2ki','열왕기하',2,6,'엘리야가 또 엘리사에게 이르되 청하건대 너는 여기 머물라 여호와께서 나를 요단으로 보내시느니라 하니 그가 이르되 여호와께서 살아 계심과 당신의 영혼이 살아 있음을 두고 맹세하노니 내가 당신을 떠나지 아니하겠나이다 하는지라 이에 두 사람이 가니라',9558),
('2ki-2-7','2ki','열왕기하',2,7,'선지자의 제자 오십 명이 가서 멀리 서서 바라보매 그 두 사람이 요단 가에 서 있더니',9559),
('2ki-2-8','2ki','열왕기하',2,8,'엘리야가 겉옷을 가지고 말아 물을 치매 물이 이리 저리 갈라지고 두 사람이 마른 땅 위로 건너더라',9560),
('2ki-2-9','2ki','열왕기하',2,9,'건너매 엘리야가 엘리사에게 이르되 나를 네게서 데려감을 당하기 전에 내가 네게 어떻게 할지를 구하라 엘리사가 이르되 당신의 성령이 하시는 역사가 갑절이나 내게 있게 하소서 하는지라',9561),
('2ki-2-10','2ki','열왕기하',2,10,'이르되 네가 어려운 일을 구하는도다 그러나 나를 네게서 데려가시는 것을 네가 보면 그 일이 네게 이루어지려니와 그렇지 아니하면 이루어지지 아니하리라 하고',9562),
('2ki-2-11','2ki','열왕기하',2,11,'두 사람이 길을 가며 말하더니 불수레와 불말들이 두 사람을 갈라놓고 엘리야가 회오리 바람으로 하늘로 올라가더라',9563),
('2ki-2-12','2ki','열왕기하',2,12,'엘리사가 보고 소리 지르되 내 아버지여 내 아버지여 이스라엘의 병거와 그 마병이여 하더니 다시 보이지 아니하는지라 이에 엘리사가 자기의 옷을 잡아 둘로 찢고',9564),
('2ki-2-13','2ki','열왕기하',2,13,'엘리야의 몸에서 떨어진 겉옷을 주워 가지고 돌아와 요단 언덕에 서서',9565),
('2ki-2-14','2ki','열왕기하',2,14,'엘리야의 몸에서 떨어진 그의 겉옷을 가지고 물을 치며 이르되 엘리야의 하나님 여호와는 어디 계시니이까 하고 그도 물을 치매 물이 이리 저리 갈라지고 엘리사가 건너니라',9566),
('2ki-2-15','2ki','열왕기하',2,15,'맞은편 여리고에 있는 선지자의 제자들이 그를 보며 말하기를 엘리야의 성령이 하시는 역사가 엘리사 위에 머물렀다 하고 가서 그에게로 나아가 땅에 엎드려 그에게 경배하고',9567),
('2ki-2-16','2ki','열왕기하',2,16,'그에게 이르되 당신의 종들에게 용감한 사람 오십 명이 있으니 청하건대 그들이 가서 당신의 주인을 찾게 하소서 염려하건대 여호와의 성령이 그를 들고 가다가 어느 산에나 어느 골짜기에 던지셨을까 하나이다 하니라 엘리사가 이르되 보내지 말라 하나',9568),
('2ki-2-17','2ki','열왕기하',2,17,'무리가 그로 부끄러워하도록 강청하매 보내라 한지라 그들이 오십 명을 보냈더니 사흘 동안을 찾되 발견하지 못하고',9569),
('2ki-2-18','2ki','열왕기하',2,18,'엘리사가 여리고에 머무는 중에 무리가 그에게 돌아오니 엘리사가 그들에게 이르되 내가 가지 말라고 너희에게 이르지 아니하였느냐 하였더라',9570),
('2ki-2-19','2ki','열왕기하',2,19,'그 성읍 사람들이 엘리사에게 말하되 우리 주인께서 보시는 바와 같이 이 성읍의 위치는 좋으나 물이 나쁘므로 토산이 익지 못하고 떨어지나이다',9571),
('2ki-2-20','2ki','열왕기하',2,20,'엘리사가 이르되 새 그릇에 소금을 담아 내게로 가져오라 하매 곧 가져온지라',9572),
('2ki-2-21','2ki','열왕기하',2,21,'엘리사가 물 근원으로 나아가서 소금을 그 가운데에 던지며 이르되 여호와의 말씀이 내가 이 물을 고쳤으니 이로부터 다시는 죽음이나 열매 맺지 못함이 없을지니라 하셨느니라 하니',9573),
('2ki-2-22','2ki','열왕기하',2,22,'그 물이 엘리사가 한 말과 같이 고쳐져서 오늘에 이르렀더라',9574),
('2ki-2-23','2ki','열왕기하',2,23,'엘리사가 거기서 벧엘로 올라가더니 그가 길에서 올라갈 때에 작은 아이들이 성읍에서 나와 그를 조롱하여 이르되 대머리여 올라가라 대머리여 올라가라 하는지라',9575),
('2ki-2-24','2ki','열왕기하',2,24,'엘리사가 뒤로 돌이켜 그들을 보고 여호와의 이름으로 저주하매 곧 수풀에서 암곰 둘이 나와서 아이들 중의 사십이 명을 찢었더라',9576),
('2ki-2-25','2ki','열왕기하',2,25,'엘리사가 거기서부터 갈멜 산으로 가고 거기서 사마리아로 돌아왔더라',9577),
('2ki-3-1','2ki','열왕기하',3,1,'유다의 여호사밧 왕 열여덟째 해에 아합의 아들 여호람이 사마리아에서 이스라엘을 열두 해 동안 다스리니라',9578),
('2ki-3-2','2ki','열왕기하',3,2,'그가 여호와 보시기에 악을 행하였으나 그의 부모와 같이 하지는 아니하였으니 이는 그가 그의 아버지가 만든 바알의 주상을 없이하였음이라',9579),
('2ki-3-3','2ki','열왕기하',3,3,'그러나 그가 느밧의 아들 여로보암이 이스라엘에게 범하게 한 그 죄를 따라 행하고 떠나지 아니하였더라',9580),
('2ki-3-4','2ki','열왕기하',3,4,'모압 왕 메사는 양을 치는 자라 새끼 양 십만 마리의 털과 숫양 십만 마리의 털을 이스라엘 왕에게 바치더니',9581),
('2ki-3-5','2ki','열왕기하',3,5,'아합이 죽은 후에 모압 왕이 이스라엘 왕을 배반한지라',9582),
('2ki-3-6','2ki','열왕기하',3,6,'그 때에 여호람 왕이 사마리아에서 나가 온 이스라엘을 둘러보고',9583),
('2ki-3-7','2ki','열왕기하',3,7,'또 가서 유다의 왕 여호사밧에게 사신을 보내 이르되 모압 왕이 나를 배반하였으니 당신은 나와 함께 가서 모압을 치시겠느냐 하니 그가 이르되 내가 올라가리이다 나는 당신과 같고 내 백성은 당신의 백성과 같고 내 말들도 당신의 말들과 같으니이다 하는지라',9584),
('2ki-3-8','2ki','열왕기하',3,8,'여호람이 이르되 우리가 어느 길로 올라가리이까 하니 그가 대답하되 에돔 광야 길로니이다 하니라',9585),
('2ki-3-9','2ki','열왕기하',3,9,'이스라엘 왕과 유다 왕과 에돔 왕이 가더니 길을 둘러 간 지 칠 일에 군사와 따라가는 가축을 먹일 물이 없는지라',9586),
('2ki-3-10','2ki','열왕기하',3,10,'이스라엘 왕이 이르되 슬프다 여호와께서 이 세 왕을 불러 모아 모압의 손에 넘기려 하시는도다 하니',9587),
('2ki-3-11','2ki','열왕기하',3,11,'여호사밧이 이르되 우리가 여호와께 물을 만한 여호와의 선지자가 여기 없느냐 하는지라 이스라엘 왕의 신하들 중의 한 사람이 대답하여 이르되 전에 엘리야의 손에 물을 붓던 사밧의 아들 엘리사가 여기 있나이다 하니',9588),
('2ki-3-12','2ki','열왕기하',3,12,'여호사밧이 이르되 여호와의 말씀이 그에게 있도다 하는지라 이에 이스라엘 왕과 여호사밧과 에돔 왕이 그에게로 내려가니라',9589),
('2ki-3-13','2ki','열왕기하',3,13,'엘리사가 이스라엘 왕에게 이르되 내가 당신과 무슨 상관이 있나이까 당신의 부친의 선지자들과 당신의 모친의 선지자들에게로 가소서 하니 이스라엘 왕이 그에게 이르되 그렇지 아니하니이다 여호와께서 이 세 왕을 불러 모아 모압의 손에 넘기려 하시나이다 하니라',9590),
('2ki-3-14','2ki','열왕기하',3,14,'엘리사가 이르되 내가 섬기는 만군의 여호와께서 살아 계심을 두고 맹세하노니 내가 만일 유다의 왕 여호사밧의 얼굴을 봄이 아니면 그 앞에서 당신을 향하지도 아니하고 보지도 아니하였으리이다',9591),
('2ki-3-15','2ki','열왕기하',3,15,'이제 내게로 거문고 탈 자를 불러오소서 하니라 거문고 타는 자가 거문고를 탈 때에 여호와의 손이 엘리사 위에 있더니',9592),
('2ki-3-16','2ki','열왕기하',3,16,'그가 이르되 여호와의 말씀이 이 골짜기에 개천을 많이 파라 하셨나이다',9593),
('2ki-3-17','2ki','열왕기하',3,17,'여호와께서 이르시기를 너희가 바람도 보지 못하고 비도 보지 못하되 이 골짜기에 물이 가득하여 너희와 너희 가축과 짐승이 마시리라 하셨나이다',9594),
('2ki-3-18','2ki','열왕기하',3,18,'이것은 여호와께서 보시기에 작은 일이라 여호와께서 모압 사람도 당신의 손에 넘기시리니',9595),
('2ki-3-19','2ki','열왕기하',3,19,'당신들이 모든 견고한 성읍과 모든 아름다운 성읍을 치고 모든 좋은 나무를 베고 모든 샘을 메우고 돌로 모든 좋은 밭을 헐리이다 하더니',9596),
('2ki-3-20','2ki','열왕기하',3,20,'아침이 되어 소제 드릴 때에 물이 에돔 쪽에서부터 흘러와 그 땅에 가득하였더라',9597),
('2ki-3-21','2ki','열왕기하',3,21,'모압의 모든 사람은 왕들이 올라와서 자기를 치려 한다 함을 듣고 갑옷 입을 만한 자로부터 그 이상이 다 모여 그 경계에 서 있더라',9598),
('2ki-3-22','2ki','열왕기하',3,22,'아침에 모압 사람이 일찍이 일어나서 해가 물에 비치므로 맞은편 물이 붉어 피와 같음을 보고',9599),
('2ki-3-23','2ki','열왕기하',3,23,'이르되 이는 피라 틀림없이 저 왕들이 싸워 서로 죽인 것이로다 모압 사람들아 이제 노략하러 가자 하고',9600),
('2ki-3-24','2ki','열왕기하',3,24,'이스라엘 진에 이르니 이스라엘 사람이 일어나 모압 사람을 쳐서 그들 앞에서 도망하게 하고 그 지경에 들어가며 모압 사람을 치고',9601),
('2ki-3-25','2ki','열왕기하',3,25,'그 성읍들을 쳐서 헐고 각기 돌을 던져 모든 좋은 밭에 가득하게 하고 모든 샘을 메우고 모든 좋은 나무를 베고 길하레셋의 돌들은 남기고 물매꾼이 두루 다니며 치니라',9602),
('2ki-3-26','2ki','열왕기하',3,26,'모압 왕이 전세가 극렬하여 당하기 어려움을 보고 칼찬 군사 칠백 명을 거느리고 돌파하여 지나서 에돔 왕에게로 가고자 하되 가지 못하고',9603),
('2ki-3-27','2ki','열왕기하',3,27,'이에 자기 왕위를 이어 왕이 될 맏아들을 데려와 성 위에서 번제를 드린지라 이스라엘에게 크게 격노함이 임하매 그들이 떠나 각기 고국으로 돌아갔더라',9604),
('2ki-4-1','2ki','열왕기하',4,1,'선지자의 제자들의 아내 중의 한 여인이 엘리사에게 부르짖어 이르되 당신의 종 나의 남편이 이미 죽었는데 당신의 종이 여호와를 경외한 줄은 당신이 아시는 바니이다 이제 빚 준 사람이 와서 나의 두 아이를 데려가 그의 종을 삼고자 하나이다 하니',9605),
('2ki-4-2','2ki','열왕기하',4,2,'엘리사가 그에게 이르되 내가 너를 위하여 어떻게 하랴 네 집에 무엇이 있는지 내게 말하라 그가 이르되 계집종의 집에 기름 한 그릇 외에는 아무것도 없나이다 하니',9606),
('2ki-4-3','2ki','열왕기하',4,3,'이르되 너는 밖에 나가서 모든 이웃에게 그릇을 빌리라 빈 그릇을 빌리되 조금 빌리지 말고',9607),
('2ki-4-4','2ki','열왕기하',4,4,'너는 네 두 아들과 함께 들어가서 문을 닫고 그 모든 그릇에 기름을 부어서 차는 대로 옮겨 놓으라 하니라',9608),
('2ki-4-5','2ki','열왕기하',4,5,'여인이 물러가서 그의 두 아들과 함께 문을 닫은 후에 그들은 그릇을 그에게로 가져오고 그는 부었더니',9609),
('2ki-4-6','2ki','열왕기하',4,6,'그릇에 다 찬지라 여인이 아들에게 이르되 또 그릇을 내게로 가져오라 하니 아들이 이르되 다른 그릇이 없나이다 하니 기름이 곧 그쳤더라',9610),
('2ki-4-7','2ki','열왕기하',4,7,'그 여인이 하나님의 사람에게 나아가서 말하니 그가 이르되 너는 가서 기름을 팔아 빚을 갚고 남은 것으로 너와 네 두 아들이 생활하라 하였더라',9611),
('2ki-4-8','2ki','열왕기하',4,8,'하루는 엘리사가 수넴에 이르렀더니 거기에 한 귀한 여인이 그를 간권하여 음식을 먹게 하였으므로 엘리사가 그 곳을 지날 때마다 음식을 먹으러 그리로 들어갔더라',9612),
('2ki-4-9','2ki','열왕기하',4,9,'여인이 그의 남편에게 이르되 항상 우리를 지나가는 이 사람은 하나님의 거룩한 사람인 줄을 내가 아노니',9613),
('2ki-4-10','2ki','열왕기하',4,10,'청하건대 우리가 그를 위하여 작은 방을 담 위에 만들고 침상과 책상과 의자와 촛대를 두사이다 그가 우리에게 이르면 거기에 머물리이다 하였더라',9614),
('2ki-4-11','2ki','열왕기하',4,11,'하루는 엘리사가 거기에 이르러 그 방에 들어가 누웠더니',9615),
('2ki-4-12','2ki','열왕기하',4,12,'자기 사환 게하시에게 이르되 이 수넴 여인을 불러오라 하니 곧 여인을 부르매 여인이 그 앞에 선지라',9616),
('2ki-4-13','2ki','열왕기하',4,13,'엘리사가 자기 사환에게 이르되 너는 그에게 이르라 네가 이같이 우리를 위하여 세심한 배려를 하는도다 내가 너를 위하여 무엇을 하랴 왕에게나 사령관에게 무슨 구할 것이 있느냐 하니 여인이 이르되 나는 내 백성 중에 거주하나이다 하니라',9617),
('2ki-4-14','2ki','열왕기하',4,14,'엘리사가 이르되 그러면 그를 위하여 무엇을 하여야 할까 하니 게하시가 대답하되 참으로 이 여인은 아들이 없고 그 남편은 늙었나이다 하니',9618),
('2ki-4-15','2ki','열왕기하',4,15,'이르되 다시 부르라 하여 부르매 여인이 문에 서니라',9619),
('2ki-4-16','2ki','열왕기하',4,16,'엘리사가 이르되 한 해가 지나 이 때쯤에 네가 아들을 안으리라 하니 여인이 이르되 아니로소이다 내 주 하나님의 사람이여 당신의 계집종을 속이지 마옵소서 하니라',9620),
('2ki-4-17','2ki','열왕기하',4,17,'여인이 과연 잉태하여 한 해가 지나 이 때쯤에 엘리사가 여인에게 말한 대로 아들을 낳았더라',9621),
('2ki-4-18','2ki','열왕기하',4,18,'그 아이가 자라매 하루는 추수꾼들에게 나가서 그의 아버지에게 이르렀더니',9622),
('2ki-4-19','2ki','열왕기하',4,19,'그의 아버지에게 이르되 내 머리야 내 머리야 하는지라 그의 아버지가 사환에게 말하여 그의 어머니에게로 데려가라 하매',9623),
('2ki-4-20','2ki','열왕기하',4,20,'곧 어머니에게로 데려갔더니 낮까지 어머니의 무릎에 앉아 있다가 죽은지라',9624),
